/** Looks up the seeded content for one country within one expedition — {code, name, days, budget, destinations, transport_to_next}. */
function rbContentFor(routeName, code, name) {
  const c = (RB_EXPEDITION_CONTENT[routeName] || {})[code] || {};
  return { code, name, days: c.days, budget: c.budget, destinations: c.destinations, transport_to_next: c.transport_to_next, notes: c.notes, lat: c.lat, lng: c.lng };
}

function rbSeedPredefinedExpeditions() {
  if (localStorage.getItem(RB_SEED_FLAG_KEY)) return;
  localStorage.setItem(RB_SEED_FLAG_KEY, '1');

  rbRoutes.push(rbBuildEurasiaRoute(), rbBuildPanAmericanRoute());
  rbSave();
}

function rbBuildEurasiaRoute() {
  const eurasia = (code, name) => rbContentFor('Eurasia Grand Tour 🌏', code, name);
  return rbBuildSeedRoute('Eurasia Grand Tour 🌏', [
    { name: 'Balkans', season: 'April–June', budget: 1909, note: 'Mild spring weather, ahead of the summer crowds and heat — fits a deliberately early start to the whole expedition.', countries: [eurasia('BA', 'Bosnia and Herzegovina'), eurasia('HR', 'Croatia'), eurasia('ME', 'Montenegro'), eurasia('AL', 'Albania'), eurasia('MK', 'North Macedonia')] },
    { name: 'Turkey', season: 'June', budget: 1300, note: 'Following on from the Balkans, still ahead of the worst summer heat in Cappadocia and the interior.', countries: [eurasia('TR', 'Turkey')] },
    { name: 'Caucasus', season: 'June–August', budget: 1475, note: 'Mountain passes and Svaneti are snow-free then; connects directly with the Central Asian mountain season.', countries: [eurasia('GE', 'Georgia'), eurasia('AM', 'Armenia'), eurasia('AZ', 'Azerbaijan')] },
    { name: 'Central Asia', season: 'June–September', budget: 2350, note: 'The Pamir Highway and high-altitude passes are only passable in these months — outside this window there is snow/ice. Turkmenistan has been deliberately cut (hard to visit / not realistic for this travel style), and Nur-Sultan/Astana has been dropped (it lay too far out of the route).', countries: [eurasia('KZ', 'Kazakhstan'), eurasia('KG', 'Kyrgyzstan'), eurasia('TJ', 'Tajikistan'), eurasia('UZ', 'Uzbekistan')] },
    { name: 'China', season: 'September', budget: 1625, note: 'After the summer crowds/heat, well ahead of the Mongolian winter cold that follows. Xinjiang has been deliberately cut (socio-political reasons); Zhangjiajie and Guilin/Yangshuo replace it.', countries: [eurasia('CN', 'China')] },
    { name: 'Mongolia', season: 'Late August–September', budget: 650, note: 'Before the freezing cold sets in from October; the Gobi is still dry and warm enough then for a multi-day 4x4 trip.', countries: [eurasia('MN', 'Mongolia')] },
    { name: 'Japan', season: 'October–November', budget: 2700, note: 'Autumn colours, and quieter than the cherry-blossom crowds in spring.', countries: [eurasia('JP', 'Japan')] },
    { name: 'Taiwan', season: 'November', budget: 750, note: 'Dry and mild, ahead of the cooler winter season in the north of the island.', countries: [eurasia('TW', 'Taiwan')] },
    { name: 'Mainland Southeast Asia', season: 'December–February', budget: 2700, note: 'The dry season on mainland Southeast Asia — no monsoon, pleasant temperatures. Myanmar has been deliberately cut (hard to visit / not realistic for this travel style). Order reversed (2026-08): Vietnam → Cambodia → Laos → Thailand, via the classic Mekong Delta and Huay Xai border crossings, instead of the earlier Vietnam-Laos order which required an unnecessary backtrack to the north.', countries: [eurasia('VN', 'Vietnam'), eurasia('KH', 'Cambodia'), eurasia('LA', 'Laos'), eurasia('TH', 'Thailand')] },
    { name: 'Maritime Southeast Asia', season: 'February–March', budget: 2735, note: 'Still dry in most regions, ahead of the monsoon that starts later in spring. Malaysia has been expanded (2026-08) with a Borneo leg (Sarawak → Brunei → Sabah, the well-known "Borneo Overland Trail") between the peninsula and Brunei — as a result, Malaysia appears twice in this route.', countries: [
      eurasia('MY', 'Malaysia'),
      {
        code: 'MY', name: 'Malaysia', days: 6, budget: 330, lat: 1.5533, lng: 110.3592,
        destinations: [{name:'Kuching',lat:1.5533,lng:110.3592}, {name:'Bako National Park',lat:1.7167,lng:110.4667}, {name:'Mulu Caves (Gunung Mulu NP)',lat:4.0428,lng:114.8144}],
        transport_to_next: 'Bus to Miri, then overland across the border to Bandar Seri Begawan, Brunei',
        notes: 'Sarawak leg of the Borneo Overland Trail (2026-08) — continuation of the peninsular block above, with Brunei as a stopover en route to Sabah.',
      },
      eurasia('BN', 'Brunei'),
      {
        code: 'MY', name: 'Malaysia', days: 11, budget: 715, lat: 5.9788, lng: 116.0753,
        destinations: [{name:'Kota Kinabalu',lat:5.9788,lng:116.0753}, {name:'Mount Kinabalu',lat:6.0754,lng:116.5580}, {name:'Sepilok Orang-oetan Centre',lat:5.8742,lng:117.9478}, {name:'Kinabatangan River',lat:5.5000,lng:118.3667}, {name:'Semporna/Sipadan',lat:4.4816,lng:118.6120}],
        transport_to_next: 'Flight Kota Kinabalu-Manila (AirAsia, ~4x/week, direct connection, ~2h)',
        notes: 'Sabah leg of the Borneo Overland Trail. Extra costs (not in the daily budget): Mount Kinabalu climb (mandatory guide+permit, ~€250-350 all-in), Sipadan diving (limited permits, ~€150-250/day).',
      },
      eurasia('PH', 'Philippines'),
    ] },
    { name: 'Indonesia & East Timor', season: 'March', budget: 1275, note: 'Dry season continues in most regions until April/May. Java and Bali have been deliberately cut (already visited) — Sumatra replaces them. East Timor connects logically here, via the land border at Kupang (West Timor).', countries: [eurasia('ID', 'Indonesia'), eurasia('TL', 'East Timor')] },
    { name: 'Singapore Finale', season: 'March', budget: 375, note: 'A deliberate, compact finale to the whole Eurasia expedition — a quiet city stop after East Timor.', countries: [eurasia('SG', 'Singapore')] },
  ], {
    best_starting_month: 'April',
    travel_style: 'Backpacker — overland where possible (bus, train, marshrutka/shared taxi), flights only where no practical ground route exists (Baku-Almaty, the island hops in Southeast Asia). Local guesthouses and hostels over international chains.',
    climate_summary: "Compared scenarios: (1) a winter start keeps the Balkans mild, but completely closes off the Pamir Highway and Song-Kul in Central Asia (impassable mountain passes) and hits Mongolia in its harshest freezing cold (-20 to -30°C); (2) a summer start (June-July) is ideal for the Caucasus and Central Asia, but puts the Balkans and Turkey in the busiest, hottest months and also lands mainland Southeast Asia right in the middle of the rainy season (June-October); (3) a start in early April keeps the Balkans in a mild spring, reaches the Caucasus/Central Asia around June-September (mountain passes open), arrives in China/Mongolia in September-October (after the summer heat, before the winter cold), reaches Japan in October-November (autumn colours), and puts all of Southeast Asia in December-March (dry season). Best choice: start in early April in the Balkans, so that almost every leg of this ~11-12 month expedition falls in its best season.",
    description: 'Overland route across Eurasia, region by region — from the Balkans through the Caucasus and Central Asia to East and Southeast Asia.',
    notes: 'Imported from a ChatGPT brainstorm — country lists per region are a reasonable starting point, adjust freely. Some countries here (parts of the Balkans, Maritime SE Asia) may already be visited or planned in your Trips sheet — worth cross-checking and possibly reusing as Block Library items instead.\n\n' +
      "Time check (2026-07): days per country have been increased after a full realism check (from 200 to 344 total days, ~11-12 months) so that each country can actually be experienced rather than just passed through — especially China (12→28), Turkey (12→24), Philippines (10→21) and Indonesia (12→21) were significantly underestimated. Turkmenistan (3 days) has deliberately been left unchanged — that's a visa constraint (transit visa), not an underestimate. Countries and order remain unchanged; only the duration per country, the region seasons/budgets above, and this climate reasoning have been added. Nevertheless, consider eventually splitting this route into two separate expeditions (West Eurasia through Central Asia, and East Eurasia/Asia) — 11-12 months in one stretch is a lot, even for slow travel.\n\n" +
      "Follow-up (2026-07): budgets per country scaled along with the increased days (same daily rate, so more days = proportionally more budget) — the region budgets above are the new totals.\n\n" +
      "Change (2026-07): Turkmenistan and Myanmar removed (hard to visit / not realistic for this travel style), East Timor added right after Indonesia, and Singapore moved to the very last block of the whole expedition as a deliberate endpoint (previously part of Maritime Southeast Asia). New total: 27 countries (was 28), 336 days, €20,000.\n\n" +
      "Prices/visa/travel-advisory verification (2026-07, second route after the Mediterranean Civilizations pilot): all 27 countries checked via web research against current prices (between budget and comfort backpacker, Youri's travel style), visa rules and the Dutch travel advisory. Days unchanged, only budgets adjusted where needed. Price corrections: North Macedonia (€46.40→€37/day — turned out to be the cheapest in the region, was budgeted too high), Mongolia (€57.50→€65/day — the Gobi jeep tour is a separate cost that pulls up the daily average), Brunei (€100→€120/day — Ulu Temburong NP requires a mandatory guide/tour), Singapore (€150→€125/day — realistic for this style, €150 built in more margin than needed). Bosnia, Croatia, Montenegro, Albania, Turkey, Georgia, Armenia, Azerbaijan, Kazakhstan, Kyrgyzstan, Tajikistan, Uzbekistan, China, Japan, Taiwan, Vietnam, Laos, Cambodia, Thailand, Malaysia, Philippines, Indonesia and East Timor turned out to already be accurate — no adjustment.\n\n" +
      "Standalone, practical additions (no price change but budget-relevant): Tajikistan (Pamir jeep €150-300 p.p. separate, GBAO permit combinable with the e-visa), Mongolia (Gobi jeep tour €75-110/day separate), Brunei (Temburong tour separate, see budget correction), Indonesia (Komodo boat trips $40-135/day separate), East Timor (Jaco Island 4x4 $85-150/day separate, limited healthcare infrastructure — good travel insurance important). Visa check: Balkan countries/Georgia/Kazakhstan/Kyrgyzstan/Uzbekistan/Turkey/Japan/Taiwan/Vietnam/Thailand/Malaysia/Brunei/Philippines/Singapore visa-free (duration varies by country); Azerbaijan/Tajikistan/Laos/Cambodia/Indonesia/East Timor use an e-visa or visa-on-arrival; China is visa-free for 30 days through 31 December 2026 (unilateral policy) — no separate Xinjiang permit needed for Kashgar/Ürümqi itself.\n\n" +
      "⚠️ Current situation Cambodia-Thailand border (July 2026): the land border crossing at Poipet is currently closed due to the border conflict between the two countries (ceasefire since late 2025, the border itself remains closed) — this route no longer uses that border (see the 2026-08 change below). Otherwise no acutely dangerous situations found on this route; a few border strips to avoid (Armenia-Azerbaijan border strip, the Philippines' Mindanao/Sulu — none of these on this route itself) — see the individual country notes above. This is a snapshot (2026-07); check nederlandwereldwijd.nl yourself shortly before departure.\n\n" +
      "Major route-logic overhaul (2026-08): every leg checked for entry/exit consistency (does the flight/bus actually match the previous/next destination, and is the order within each country geographically logical) — see the individual country notes above for details per country. Key changes: Croatia reduced to just Dubrovnik (already visited elsewhere); Albania, Turkey, Georgia, Armenia, Azerbaijan and Uzbekistan reordered for a better connection; Kazakhstan without Nur-Sultan/Astana (too far out of the route); Xinjiang fully replaced by Zhangjiajie and Guilin/Yangshuo in China (socio-political reason); Vietnam revised (Ha Giang Loop added, Hue/Hoi An/Da Nang cut, Da Lat and Phu Quoc as side trips from Ho Chi Minh City); country order Vietnam-Cambodia-Laos-Thailand reversed (was Vietnam-Laos-Cambodia-Thailand); Thailand-Malaysia now by boat (Koh Lipe-Langkawi) instead of overland; Malaysia expanded with a Borneo leg (Sarawak-Brunei-Sabah, the Borneo Overland Trail); Philippines converted to a round trip instead of a fixed base in Manila; Indonesia with Sumatra instead of Java/Bali. New total: 27 countries, ~338 days, ~€19,850 (was 336 days/€20,000).",
  });
}

function rbBuildPanAmericanRoute() {
  const panAm = (code, name) => rbContentFor('Pan-American Grand Tour 🌎', code, name);
  return rbBuildSeedRoute('Pan-American Grand Tour 🌎', [
    { name: 'Mexico', season: 'November–December', budget: 1000, note: 'Dry season, after the summer rains.', countries: [panAm('MX', 'Mexico')] },
    { name: 'Northern Central America', season: 'December–January', budget: 1770, note: 'Dry season, hurricane season over.', countries: [panAm('GT', 'Guatemala'), panAm('BZ', 'Belize'), panAm('HN', 'Honduras'), panAm('SV', 'El Salvador')] },
    { name: 'Southern Central America', season: 'January–February', budget: 1975, note: 'Pacific dry season in Costa Rica/Panama — best time for the coast.', countries: [panAm('NI', 'Nicaragua'), panAm('CR', 'Costa Rica'), panAm('PA', 'Panama')] },
    { name: 'Colombia', season: 'February–March', budget: 1260, note: 'Dry in both the Caribbean region and the coffee zone/Andes.', countries: [panAm('CO', 'Colombia')] },
    { name: 'Ecuador', season: 'March–April', budget: 1650, note: 'Sierra dry enough for hiking; Galápagos is good year-round but quieter in this season.', countries: [panAm('EC', 'Ecuador')] },
    { name: 'Peru', season: 'April–May', budget: 1050, note: 'The Andes dry season begins — ideal for Cusco/Sacred Valley and Huaraz trekking.', countries: [panAm('PE', 'Peru')] },
    { name: 'Bolivia', season: 'May–June', budget: 344, note: 'Dry season, clear Uyuni Salt Flat (note: no mirror effect like in the wet season — a deliberate trade-off).', countries: [panAm('BO', 'Bolivia')] },
    { name: 'Northern Chile', season: 'June–July', budget: 520, note: 'Northern Chile only (Atacama, Antofagasta) — Patagonia is a separate future expedition. The Atacama is dry year-round; cold nights in the Chilean winter, fine during the day.', countries: [panAm('CL', 'Chile')] },
    { name: 'Northern Argentina', season: 'July', budget: 350, note: 'Northern Argentina only (Salta, Jujuy) — Patagonia is a separate future expedition. Dry peak season in Salta/Jujuy, cold nights in the high mountains.', countries: [panAm('AR', 'Argentina')] },
    { name: 'Southern Brazil', season: 'July–August', budget: 1166, note: 'Southern Brazil only — Northern Brazil is a separate future expedition. Southern Brazilian winter: mild and dry for sightseeing (Iguaçu, colonial towns), but not beach weather; for beach time start the whole trip 1-2 months later.', countries: [panAm('BR', 'Brazil')] },
  ], {
    best_starting_month: 'November',
    travel_style: 'Backpacker — local buses (chicken bus to fancier overland bus) through Central America and the Andes, the occasional domestic flight where the distance justifies it (e.g. Salta-Foz do Iguaçu), sailboat through the San Blas Islands instead of flying over the Darién Gap.',
    climate_summary: "This route was already designed climate-optimized (hence the November start) — the region seasons above make that explicit: each region gets the month that follows from a gradual push southward starting November 1st, all the way to Southern Brazil around July-August. The one drawback of this setup: on a ~9-month trip, the coastal finale in Southern Brazil (Florianópolis, beaches) falls in the South American winter — fine for sightseeing (Iguaçu, colonial towns), but not beach weather. Anyone who cares about beach time in Brazil can start the whole trip 1-2 months later, or shave a few days off the earlier regions so the finale lands back in the shoulder season.",
    description: 'Climate-optimized route down the Americas, from Mexico to southern Brazil.',
    notes: 'Best started around November 1st (pick your target year and fill in the exact start date above). Patagonia, Antarctica, Northern Brazil, Suriname and the Caribbean are intentionally excluded — planned as separate future expeditions. Imported from a ChatGPT brainstorm — adjust country lists/regions as needed.\n\n' +
      "Time check (2026-07): this was already the best-paced expedition (274→286 days, adjusted only slightly) — Guatemala through Ecuador and Bolivia each gained a few extra days, while Northern Chile and Northern Argentina were actually shortened (12→10 and 14→10) because one desert region didn't need the full original time; Mexico, Colombia and Peru were already ideal and unchanged. The region-level seasons above follow the November start month by month southward; note that this puts the Southern Brazil finale in the South American winter (mild, fine for sightseeing, but not beach weather).\n\n" +
      "Follow-up (2026-07): budgets per country scaled along with the adjusted days — the region budgets above are the new totals.\n\n" +
      "Price/visa/travel-advisory verification (2026-07): Belize (€57.50→€72/day, water taxis between islands), Colombia (€28.57→€36/day), Ecuador (€1,025→€1,650 total, Galápagos park/transit costs + boat/land tour weren't covered), Northern Chile (€40→€52/day, San Pedro is expensive) and Southern Brazil (€45.45→€53/day, Rio/São Paulo) corrected. Mexico, Guatemala, Honduras, El Salvador, Nicaragua, Costa Rica, Panama, Peru, Bolivia and Northern Argentina confirmed accurate. See the individual country notes above for travel-advisory/visa details (incl. Honduras' orange provinces, El Salvador's state of emergency, the CA-4 combined visa limit, Peru/Bolivia's current states of emergency).\n\n" +
      "Route-logic revision (2026-08, search-confirmed, eleventh expedition from ROUTE_LOGIC_REVIEW.md, biggest route in this round — 15 countries): four fixes. (1) **Mexico**: San Cristóbal de las Casas used to come after Bacalar — a ≈700 km/10h backtrack past Palenque, ground the trip had already covered. Now between Oaxaca and Palenque (the standard 'Ruta Maya' order). (2) **Belize-Honduras ferry**: the text 'via Livingston, Guatemala' turned out to be incorrect — the actual ferry services (Placencia/Dangriga-Puerto Cortés) run direct, no Guatemala stopover. Corrected. (3) **Honduras**: Tegucigalpa used to come before La Ceiba/Roatán (north coast), while the border crossing to El Salvador actually lies south via Tegucigalpa — that meant going north and then back south again. Now north coast first (La Ceiba/Roatán), Tegucigalpa last. (4) **Bolivia**: Santa Cruz (eastern lowlands) dropped — Youri's own call after a targeted question — it sat ≈638 km from Potosí and would then need another ≈850 km back towards Uyuni/Chile, a dead end with no continuation. The existing transport text ('via the Uyuni Salt Flat tour') already implicitly assumed departure from Uyuni, not Santa Cruz — an unspoken clue that was already there. Bolivia's days/budget scaled down proportionally (21→17 days, €425→€344). Confirmed without change: Guatemala's internal order, Colombia's Medellín-Salento-Bogotá-San Agustín (already minimizes Bogotá's unavoidable detour), and Ecuador's Otavalo/Mindo structure (normal hub-and-spoke from Quito, no zigzag). Coordinates added per destination for all 15 countries. Youri had previously only visited Yucatán (Mexico) and Lake Atitlán/Antigua/Acatenango (Guatemala), nothing else — no cuts there. Same fixes also applied to the four split companions (Mexico 🌵, Central America Loop 🌋, Andes Grand Traverse 🦙, Southern Cone & Brazil Finale 🧉) via the shared RB_EXPEDITION_CONTENT table.",
  });
}

function rbSeedMEAExpedition() {
  if (localStorage.getItem(RB_SEED_FLAG_KEY_MEA)) return;
  localStorage.setItem(RB_SEED_FLAG_KEY_MEA, '1');

  rbRoutes.push(rbBuildAfricaGrandTourRoute());
  rbSave();
}

/**
 * Africa Grand Tour — reordered 2026-07 to fix a real seasonal problem, at Youri's request. The
 * original north-to-south order (Egypt → East Africa → Islands → Southern Africa → South Africa
 * Finale) claimed East Africa's and Southern Africa's dry seasons were "opposite" and therefore
 * unfixable — verified via web research that this is FALSE: East Africa's dry season (June-October)
 * and Southern Africa's dry season (May-October) mostly OVERLAP. The real problem was sequencing:
 * doing both back-to-back with the Islands in between meant Southern Africa (the second of the two)
 * only arrived in November, already past the shared window and into its wet season.
 *
 * Research also surfaced a second, previously undocumented problem: Ethiopia's main rains (kiremt)
 * fall exactly June-September — the opposite of what the old route assumed when it bundled Ethiopia
 * into the same "June-September dry season" logic as Kenya/Uganda/Rwanda/Tanzania. Ethiopia's own
 * good window is October-March (peak December-February).
 *
 * Fix: reversed to a south-to-north sweep, starting in Southern Africa (which has no comparably good
 * secondary season — its wet season genuinely degrades game viewing) and ending with East Africa's
 * secondary dry pocket (January-February, still a recognized good window — southern Serengeti calving
 * season) rather than forcing Southern Africa into that trade-off instead. Ethiopia and Egypt move to
 * the very end as a "Horn of Africa & Egypt" finale, landing in Ethiopia's actual good season and,
 * as a bonus, moving Egypt out of early-summer heat into its comfortable cool season. No countries
 * added or removed, no days/budget changed per country — same 18 countries, same total (288 days,
 * €29.225), just resequenced. Every new adjacency uses a real border crossing or a realistic flight
 * (see individual transport_to_next fields); the Angola-Zambia crossing is flagged as less-traveled
 * and worth extra pre-trip verification.
 */
function rbBuildAfricaGrandTourRoute() {
  const mea = (code, name) => rbContentFor('Africa Grand Tour 🌍', code, name);
  return rbBuildSeedRoute('Africa Grand Tour 🌍', [
    {
      name: 'South Africa, Lesotho & Eswatini', season: 'June–early July', budget: 2975,
      note: 'The opener of the expedition, with a real international airport as the entry point (Cape Town/Johannesburg) — Kruger wildlife spotting is at its best here, well before the rainy season.',
      countries: [mea('ZA', 'South Africa'), mea('LS', 'Lesotho'), mea('SZ', 'Eswatini')],
    },
    {
      name: 'Southern Africa', season: 'July–October', budget: 14035,
      note: "From Mozambique to Malawi via Zimbabwe, Botswana, Namibia, Angola and Zambia — with this order it falls almost entirely within the dry season (May-October), with the best wildlife viewing right toward the end (August-October). The Angola-Zambia border crossing in southeastern Angola is less traveled than the rest of this route — check extra carefully beforehand.",
      countries: [mea('MZ', 'Mozambique'), mea('ZW', 'Zimbabwe'), mea('BW', 'Botswana'), mea('NA', 'Namibia'), mea('AO', 'Angola'), mea('ZM', 'Zambia'), mea('MW', 'Malawi')],
    },
    {
      name: 'Islands', season: 'October–November', budget: 2650,
      note: "Madagascar and Mauritius — Madagascar's notoriously slow roads are the biggest time sink here, not the sights themselves.",
      countries: [mea('MG', 'Madagascar'), mea('MU', 'Mauritius')],
    },
    {
      name: 'East Africa', season: 'November–January', budget: 10320,
      note: "Tanzania, Rwanda, Uganda and Kenya — lands in the short rains (October-December, light afternoon showers, manageable) and the following short dry spell (January-February), including the southern Serengeti's calving season. Not the absolute peak (June-October, which here coincides with Southern Africa's only good season), but a recognized strong alternative.",
      countries: [mea('TZ', 'Tanzania'), mea('RW', 'Rwanda'), mea('UG', 'Uganda'), mea('KE', 'Kenya')],
    },
    {
      name: 'Horn of Africa & Egypt', season: 'February–March', budget: 3115,
      note: "Ethiopia and Egypt as the finale. Ethiopia's main rainy season (kiremt) falls June-September — the old order accidentally dropped Ethiopia right in the middle of it; here it lands in its own good window (October-March, peak December-February). As an added bonus, Egypt benefits from the cooler late season instead of the early summer heat.",
      countries: [mea('ET', 'Ethiopia'), mea('EG', 'Egypt')],
    },
  ], {
    best_starting_month: 'June',
    travel_style: 'Overland/safari trucks between parks, mandatory local guides for gorilla trekking (Uganda/Rwanda), a mix of budget lodges and camping in the national parks, flights only between Malawi/Madagascar/Mauritius/Tanzania (no overland route possible across water) and between Ethiopia and Egypt (no practical overland route through Sudan).',
    climate_summary: "Compared scenarios, after research (2026-07) confirmed that the \"opposite dry/wet cycles\" assumption from the old order was incorrect: East Africa's dry season (June-October) and Southern Africa's dry season (May-October) actually overlap for the most part. The real problem was the order: with a June start and the old country order (East Africa first, Southern Africa only after the islands), Southern Africa didn't arrive until November — already past the shared window and in the middle of the rainy season. With the current, reversed order (south to north), Southern Africa — which has no comparably strong alternative season — gets the shared June-October window, and East Africa shifts to November-January: not the absolute peak, but a recognized strong season nonetheless (short rains plus the southern Serengeti's calving season in January-February). An additional fix: Ethiopia's main rainy season (kiremt, June-September) was accidentally bundled with the rest of East Africa's dry season in the old order — here Ethiopia lands in its own good window (October-March, peak December-February) at the end of the trip, together with Egypt, which is likewise taken out of the old order's early-summer heat. Best choice: start in early June in South Africa.",
    description: 'Overland route from southern Africa via East Africa and the islands to the Horn of Africa and Egypt as the finale. Intended duration ~9.5 months.',
    notes: 'Originally imported from a ChatGPT brainstorm, with Egypt as the starting point/northern gateway. Jordan and Oman used to belong to this route but were moved to what is now Mediterranean Civilizations Expedition 🏛️, so this stays purely African + Egypt as a historical/geographical connector; Egypt itself appears in both routes because it fits both themes. South Africa is already marked as "visited" in your Countries sheet — worth checking before treating it as new.\n\n' +
      'Time check (2026-07): days per country increased after a realism check (247→277 days total) — especially Uganda (gorilla trekking logistics), Madagascar (notoriously slow roads) and Mozambique (the country stretches enormously north-south) had been underestimated.\n\n' +
      'Follow-up (2026-07): budgets per country scaled along with the increased days, and the 18 countries grouped into regions with their own season/budget, as Eurasia and Pan-American already had.\n\n' +
      "Addition (2026-07): Angola added between Namibia and Zambia (Oshikango/Santa Clara border crossing from Namibia, onward to Zambia via a less-traveled border crossing in southeastern Angola). Sourced from the West & Central Africa design session — there Angola fit geographically worse (only reachable by flight, no neighboring countries on that route). New total after this addition: 18 countries (was 17), 288 days (was 277), €29,225 (was €27,725).\n\n" +
      "Reversed to a south-north order (2026-07), at Youri's request to improve the East/Southern Africa seasonal compromise — see the climate_summary above for the full reasoning. All 18 countries, days and budgets per country are unchanged; only the order, the region grouping/names, and the transport_to_next routes (now in the reverse direction, with a few new border crossings where the order required it) were adjusted. This is a deliberate, wholesale replacement of the route (as with Mediterranean Civilizations Expedition previously), not a field patch — any of your own adjustments already made to individual fields will be lost here.\n\n" +
      "Price/visa/travel advisory verification (2026-07, the twelfth route in this verification round, along with British Isles the last two): all 18 countries checked via web research against current prices (between budget and comfort backpacker), visa rules and Dutch travel advisory. Days unchanged everywhere; only budgets adjusted. Biggest correction: Namibia (€100→€200/day) — no longer visa-free for Dutch nationals since April 2025, plus a 4x4 rental car necessary almost everywhere on the route. Also up substantially: South Africa, Mozambique, Botswana, Angola, Malawi, Tanzania, Rwanda, Kenya and Uganda (see each country's own note for the reason — often a visa change, increased park fees, or a cost that wasn't previously accounted for). One clear decrease: Madagascar (€78→€69/day — base costs turned out lower on inquiry, while the island flight to Nosy Be and the private 4x4 transfers are now called out separately instead of hidden in the daily budget). Lesotho, Zimbabwe (base budget) and Mauritius confirmed accurate, no change. Zambia confirmed accurate provided the self-drive/camping style is maintained at South Luangwa/Lower Zambezi instead of all-inclusive safari lodges. New total: €33,095 (was €29,225), 288 days unchanged.\n\n" +
      "⚠️ Most important standalone finding: Lalibela, Gondar and the Simien Mountains (Amhara region) and the Danakil Depression (Afar region) currently sit entirely RED ('do not travel') on the Dutch travel advisory due to the Fano militia conflict and border instability with Eritrea respectively — see Ethiopia's own note for the full explanation. Youri has deliberately chosen to leave this leg unchanged (Route Builder is the aspirational/someday layer), but this is a snapshot (July 2026): check nederlandwereldwijd.nl yourself shortly before any actual trip. Two other route pieces deserve extra attention when actually booking: Rwanda's 'Lake Kivu' stop has been clarified to Kibuye/Karongi (not Rubavu/Gisenyi, which sits across from M23-held Goma and is orange), and Uganda's Queen Elizabeth NP/Bwindi corridor has a temporary DRC border closure (Ebola outbreak) and an ADF-related attack on nearby towns (Nov 2025) — both discussed in their own country notes.\n\n" +
      "Route-logic revision (2026-08, search-confirmed, thirteenth and final expedition from ROUTE_LOGIC_REVIEW.md, the most individual fixes of the whole playbook): nine countries with a genuine reordering, plus Ethiopia's unstated return flight. **South Africa**: Kruger used to come before Johannesburg, while the Addo-Kruger route runs straight through Johannesburg — now Addo→Johannesburg→Kruger, saving ≈465 km. **Lesotho**: 'Sani Pass/Thaba-Bosiu' used to be merged into one destination while they lie ≈335 km apart — now separate, Sani Pass as the last stop (comes out directly in KZN, close to the Eswatini border crossing). **Mozambique**: the leg entered at Maputo but started with Ilha de Moçambique (≈2,000+ km further away) and ended back at Maputo just before a ≈1,644 km drive to Zimbabwe — now Maputo first, then south-to-north on to Nampula/Ilha, closer to the Zimbabwe border. **Zimbabwe**: Victoria Falls-Hwange-Mana Pools-Great Zimbabwe-Bulawayo crossed the country diagonally at least twice — now Mana Pools (at entry) →Great Zimbabwe→Bulawayo→Hwange→Victoria Falls, one loop. **Namibia** (biggest find): Fish River Canyon used to be the last stop (far south) while the Angola border is in the far north — the old order cost ≈2,490 km of pure there-and-back detour; now Fish River Canyon early in the route, ending at Etosha (north) — saving ≈1,355 km (≈35%). **Angola**: Luanda used to come first, ≈900-1,000 km from entry and from the rest of the destinations (which cluster in the south) — now the southern cluster first, Luanda as a separate flight side trip at the end. **Zambia**: South Luangwa (east) used to come before Livingstone (south) while the Malawi border is actually on the east side — now the southern loop first, South Luangwa last. **Madagascar**: Isalo used to come after Morondava, connected by a rough ≈600 km unpaved track — now reached via the good paved RN7 from Tana, no longer connecting to Morondava. **Tanzania**: Kilimanjaro (close to Arusha) used to come after Zanzibar, which cost a return flight of ≈460-600 km — now right after the northern circuit, before Zanzibar. **Uganda**: the leg entered from Rwanda close to Bwindi, but started with Kampala/Jinja on the other side of the country — now Bwindi/QENP/Kibale right upon entry, Kampala/Jinja last (connecting to the Kenya border). **Kenya**: Mount Kenya used to come before Mombasa, which cost an extra trip via Nairobi — now Mount Kenya last, connecting directly to the Moyale route toward Ethiopia. **Ethiopia**: the return flight Omo Valley-Addis Ababa (no direct international flight from the Omo Valley) was nowhere stated — now explicitly added. Confirmed with no change: Eswatini, Botswana. Coordinates per destination added to all 18 countries. Youri had only visited Cape Town before (can stay) — no cuts. The same fixes were also applied to the four split companions (Southern Africa Safari Loop 🦁, African Islands 🏝️, East Africa Safari Classic 🦒, Horn of Africa & Egypt 🏺) via the shared RB_EXPEDITION_CONTENT table. Countries/days/budget unchanged — only order, transport notes and coordinates adjusted. **This completes all 13 original expeditions from ROUTE_LOGIC_REVIEW.md.**",
  });
}

function rbSeedAncientCivilizationsExpedition() {
  if (localStorage.getItem(RB_SEED_FLAG_KEY_ANCIENT)) return;
  localStorage.setItem(RB_SEED_FLAG_KEY_ANCIENT, '1');

  rbRoutes.push(rbBuildMediterraneanExpeditionRoute());
  rbSave();
}

